// Cross-boundary regression for the Control Center's "Club admin pages"
// quick actions (bug #2, Nov 24): the six destinations are rendered with
// payloads captured from the REAL worker handlers (fixture generated by
// worker/native/capture-links.test.ts from a production-analogous club:
// Active PBE season, owner + 2 students, owner self-assignment, draft
// proposals, a live release, news draft + published, a pending invitation,
// non-zero XP). Page tests that hand-write API fixtures cannot see a
// client/server field drift; this test feeds one side's real output into
// the other, which is the lesson of the Nov 24 Content-tab crash.
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { Component, type ReactNode } from "react";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { AppShell } from "../../layouts/AppShell";
import { afterEach, beforeAll, expect, it, vi } from "vitest";
import { ToastProvider } from "../../components/ui";
import { AdminHomePage } from "./AdminHomePage";
import { CoachesPage } from "./CoachesPage";
import { MaterialsPage } from "./MaterialsPage";
import { SeasonsListPage, StudentsPage } from "./SimpleAdminPages";
import { DisputeQueue } from "../practice/DisputeQueue";
import fixture from "./__fixtures__/club-admin-payloads.json";

type Captured = { status: number; body: unknown };
const payloads = fixture as unknown as Record<string, Captured>;
const me = { ...(payloads.me.body as Record<string, unknown>), email: "viticopq12@gmail.com", organizationName: "WinterPark" };

vi.mock("../../auth/AuthContext", () => ({
  useAuth: () => ({ me, loading: false, error: null, refresh: vi.fn() }),
}));

afterEach(() => cleanup());

const unrouted: string[] = [];
function route(rawUrl: string): Captured {
  const url = new URL(rawUrl, "https://erudoza.test");
  const p = url.pathname;
  const org = "/api/v1/organizations/";
  if (p === "/api/v1/me") return payloads.me;
  if (p === "/api/v1/auth/coach-options") return payloads["coach-options"];
  if (p === "/api/v1/pbe/disputes") return payloads.disputes;
  if (p === "/api/v1/progress/me/today") return payloads["training-today"];
  if (p === "/api/v1/profile/identities") return payloads.identities;
  if (p === "/api/v1/profile/me/notifications") return payloads.notifications;
  if (p === "/api/v1/profile/me") return payloads["profile-me"];
  if (p.startsWith(org)) {
    const rest = p.slice(org.length).split("/").slice(1).join("/");
    if (rest === "seasons") return payloads.seasons;
    if (rest.endsWith("/coverage")) return payloads.coverage;
    if (rest === "students") return payloads.students;
    if (rest === "engagement") return payloads.engagement;
    if (rest === "coaches") return payloads.coaches;
    if (rest === "coach-invitations") return payloads["coach-invitations"];
    if (rest === "pbe-materials/releases") return payloads["pbe-releases"];
    if (rest.startsWith("pbe-materials/releases/")) return payloads["pbe-release-detail"];
    if (rest === "pbe-materials") return payloads["pbe-materials"];
    if (rest === "pbe-news/articles") return payloads["pbe-news-articles"];
    if (rest === "practice/bootstrap") return payloads["practice-bootstrap"];
  }
  unrouted.push(p + url.search);
  return { status: 404, body: { detail: "unrouted in club-admin-links test" } };
}

beforeAll(() => {
  vi.stubGlobal("fetch", vi.fn(async (input: RequestInfo | URL) => {
    const { status, body } = route(String(input));
    return new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });
  }));
});

class Boundary extends Component<{ children: ReactNode }, { error: Error | null }> {
  state = { error: null as Error | null };
  static getDerivedStateFromError(error: Error) { return { error }; }
  render() { return this.state.error ? <div data-testid="boundary-error">{String(this.state.error)}</div> : this.props.children; }
}

function renderPage(element: ReactNode) {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  const view = render(
    <QueryClientProvider client={client}>
      <ToastProvider>
        <MemoryRouter>
          <Boundary>{element}</Boundary>
        </MemoryRouter>
      </ToastProvider>
    </QueryClientProvider>,
  );
  return view;
}

function expectNoBoundaryError() {
  expect(screen.queryByTestId("boundary-error")).toBeNull();
}

it("Overview (/admin) renders on real payloads", async () => {
  renderPage(<AdminHomePage />);
  expect(await screen.findByRole("table")).toBeInTheDocument();
  expect(screen.getByRole("combobox", { name: "Season" })).toHaveValue((payloads.meta.body as { seasonId: string }).seasonId);
  expect(screen.getByText("Ana Example")).toBeInTheDocument();
  expect(screen.getByText("Ben Example")).toBeInTheDocument();
  expectNoBoundaryError();
});

it("Students (/admin/students) renders directory and engagement on real payloads", async () => {
  renderPage(<StudentsPage />);
  expect((await screen.findAllByText("Ana Example")).length).toBeGreaterThan(0);
  expect(screen.getAllByText("Ben Example").length).toBeGreaterThan(0);
  fireEvent.click(screen.getByRole("tab", { name: "Engagement" }));
  expect(await screen.findByText("65")).toBeInTheDocument(); // Ana's real XP-this-week from the captured engagement row
  expectNoBoundaryError();
});

it("Coaches (/admin/coaches) renders directory and invitations on real payloads", async () => {
  renderPage(<CoachesPage />);
  expect(await screen.findByText("newcoach@example.com")).toBeInTheDocument();
  expect(screen.getByText("Coach directory")).toBeInTheDocument();
  expectNoBoundaryError();
});

it("Seasons (/admin/seasons) renders on real payloads", async () => {
  renderPage(<SeasonsListPage />);
  expect(await screen.findByText("Summer 2027")).toBeInTheDocument();
  expectNoBoundaryError();
});

it("Materials & news (/admin/materials) renders proposals, proposal detail, and news on real payloads", async () => {
  renderPage(<MaterialsPage />);
  expect(await screen.findByText("2026–27")).toBeInTheDocument();
  expect(screen.getByText("2027–28")).toBeInTheDocument();
  const reviewButtons = screen.getAllByRole("button", { name: "Review" });
  fireEvent.click(reviewButtons[0]);
  expect(await screen.findByText(/Changes compared with the live release/)).toBeInTheDocument();
  expectNoBoundaryError();
  fireEvent.click(screen.getByRole("tab", { name: "News" }));
  expect(await screen.findByText("Regional finals recap")).toBeInTheDocument();
  expect(screen.getByText("PBE kickoff announced")).toBeInTheDocument();
  expectNoBoundaryError();
});

it("Answer reviews (/admin/practice/reviews) renders the empty queue on real payloads", async () => {
  renderPage(<DisputeQueue />);
  expect(await screen.findByText("No pending reviews or evidence updates")).toBeInTheDocument();
  expectNoBoundaryError();
});

it("routes every fetch the six pages make", () => {
  expect(unrouted).toEqual([]);
});

// The quick actions navigate from the Control Center (which renders its own
// shell) into the club workspace, so the destination only exists composed
// inside the coach AppShell (masthead, bell, shortcut bar, outlet). Render
// that full composition at each quick-action path.
function renderInShell(path: string) {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  return render(
    <QueryClientProvider client={client}>
      <ToastProvider>
        <MemoryRouter initialEntries={[path]}>
          <Boundary>
            <Routes>
              <Route path="/admin" element={<AppShell variant="admin" />}>
                <Route index element={<AdminHomePage />} />
                <Route path="students" element={<StudentsPage />} />
                <Route path="coaches" element={<CoachesPage />} />
                <Route path="seasons" element={<SeasonsListPage />} />
                <Route path="materials" element={<MaterialsPage />} />
                <Route path="practice/reviews" element={<DisputeQueue />} />
              </Route>
            </Routes>
          </Boundary>
        </MemoryRouter>
      </ToastProvider>
    </QueryClientProvider>,
  );
}

it.each([
  ["/admin", "Season overview"],
  ["/admin/students", "Ana Example"],
  ["/admin/coaches", "Coach directory"],
  ["/admin/seasons", "Summer 2027"],
  ["/admin/materials", "2026–27"],
  ["/admin/practice/reviews", "No pending reviews or evidence updates"],
])("quick action to %s renders inside the coach shell", async (path, marker) => {
  renderInShell(path);
  expect((await screen.findAllByText(marker, {}, { timeout: 10000 })).length).toBeGreaterThan(0);
  expect(screen.getByTestId("coach-app-shell")).toBeInTheDocument();
  expectNoBoundaryError();
}, 20000);
